-- Schema conventions (M2, task 2.1). Generated by `prisma migrate diff`, then EDITED BY HAND:
-- every timestamp conversion has `USING <col> AT TIME ZONE 'UTC'` (ADR-0023).
-- Without it, PostgreSQL reads each old value in the SESSION time zone: on a server whose
-- session is not UTC, every stored instant would silently shift by the offset.
-- Prisma always wrote UTC wall-clock values into these columns, so 'UTC' is the correct source zone.

-- users.email: full unique constraint replaced by a partial one below (ADR-0022)
-- DropIndex
DROP INDEX "users_email_key";

-- AlterTable
ALTER TABLE "refresh_tokens"
  ALTER COLUMN "expires_at" SET DATA TYPE TIMESTAMPTZ(3) USING "expires_at" AT TIME ZONE 'UTC',
  ALTER COLUMN "created_at" SET DATA TYPE TIMESTAMPTZ(3) USING "created_at" AT TIME ZONE 'UTC';

-- AlterTable
-- email: register already caps the input at 254 characters, so no existing row is longer
ALTER TABLE "users"
  ALTER COLUMN "email" SET DATA TYPE VARCHAR(254),
  ALTER COLUMN "last_login_at" SET DATA TYPE TIMESTAMPTZ(3) USING "last_login_at" AT TIME ZONE 'UTC',
  ALTER COLUMN "deleted_at" SET DATA TYPE TIMESTAMPTZ(3) USING "deleted_at" AT TIME ZONE 'UTC',
  ALTER COLUMN "created_at" SET DATA TYPE TIMESTAMPTZ(3) USING "created_at" AT TIME ZONE 'UTC',
  ALTER COLUMN "updated_at" SET DATA TYPE TIMESTAMPTZ(3) USING "updated_at" AT TIME ZONE 'UTC';

-- CreateIndex
-- Unique among non-deleted Users only (ADR-0022). Declared in schema.prisma with the
-- `partialIndexes` preview feature, so later generated migrations keep it.
CREATE UNIQUE INDEX "users_email_key" ON "users"("email") WHERE ("deleted_at" IS NULL);
